// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz parameters: from (address), v (uint256), and a boolean that chooses whether the callee should revert
    function testFuzz_property(address from, uint256 v, bool calleeReverts) public {
        // keep _tos length exactly 1 to simplify observation while keeping fuzz wide
        address[] memory tos = new address[](1);

        // Deploy a helper that either reverts or records the call depending on calleeReverts.
        // Use two instances so we can pass one address; choose which one to use based on calleeReverts.
        RevertingC reverter = new RevertingC();
        RecordingC recorder = new RecordingC();

        address callee = calleeReverts ? address(reverter) : address(recorder);

        tos[0] = address(0x1234); // recipient argument passed through to callee; fuzzing it isn't necessary

        // Call c.transfer and observe whether it reverted.
        bool ok;
        try c.transfer(from, callee, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the reference implementation always reverts when the callee reverts.
        // So when we direct the call to the reverting helper, the reference must revert (ok == false).
        // The buggy mutant (which ignores the callee's success flag) will return true (ok == true) in that case.
        if (calleeReverts) {
            // exactly one assert reading c's behavior (via the try/catch result)
            assertTrue(!ok);
        } else {
            // when callee does NOT revert, transfer should succeed
            assertTrue(ok);
        }
    }
}

// Helper that always reverts when its transferFrom is called
contract RevertingC {
    // match selector: transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure {
        revert("revert in callee");
    }
}

// Helper that records calls to transferFrom (not strictly needed for the assertion but provided to match requirements)
contract RecordingC {
    event Called(address from, address to, uint256 value);
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        emit Called(from, to, value);
        return true;
    }
}
